insert into lesson (id, track, position, title, objective, body, example, is_question_bank) values
('java-qb-object-contracts', 'JAVA', 201, 'Java 对象模型与契约', '根据代码判断对象相等性、方法分派以及拷贝后的共享状态。',
 '阅读题目中的静态类型和运行时类型，检查比较、调用、赋值各自依赖的规则。',
 '例如，浅拷贝之后，两个对象的数组字段可能仍指向同一个数组。', true),
('java-qb-collections-generics', 'JAVA', 202, 'Java 集合与泛型', '根据顺序、去重、遍历和类型约束选择集合与方法签名。',
 '区分集合的迭代顺序与取出顺序，并判断类型参数在编译期提供了什么保证。',
 '例如，优先队列的 poll 按优先级取出元素，迭代器没有排序保证。', true),
('java-qb-concurrency', 'JAVA', 203, 'Java 并发', '判断共享状态、线程池调度、任务异常与资源限流的行为。',
 '分析多个线程之间的可见性和原子性，追踪工作线程复用时的状态以及任务失败的观察方式。',
 '例如，任务把上下文写入 ThreadLocal 后，可在 finally 中清理当前线程的值。', true),
('java-qb-jvm', 'JAVA', 204, 'JVM 类加载与内存', '区分类的加载与初始化、栈和堆的职责以及对象的可达性。',
 '通过插件加载、栈溢出和堆占用增长等场景，在 JVM 规范与诊断工具之间建立对应关系。',
 '例如，两个加载器各自定义同名类时，两个类拥有不同的运行时身份。', true),
('java-qb-spring-di-mvc', 'JAVA', 205, 'Spring 依赖注入与 MVC', '解决 Bean 装配问题，并追踪 MVC 请求、响应和异常处理过程。',
 '从容器选择依赖开始，区分 Bean 作用域、控制器参数绑定、请求分派与视图解析。',
 '例如，HandlerMapping 选择请求处理器，HandlerAdapter 负责调用该处理器。', true),
('java-qb-spring-tx-jpa', 'JAVA', 206, 'Spring 事务与 JPA', '判断事务是否生效以及何时回滚，分析实体状态、关联查询和并发更新。',
 '把 Spring 事务代理和数据库事务边界与 JPA 持久化上下文中的实体状态变化联系起来。',
 '例如，merge 返回托管实例。继续修改分离状态的原对象不会自动同步。', true);

insert into question (id, lesson_id, prompt, option_a, option_b, option_c, correct_option, explanation,
                      source_type, source_title, source_url, reference_url) values
-- Java 对象模型与契约
(201, 'java-qb-object-contracts', '退款单 Refund 继承 Invoice。Invoice.equals 接受编号相同的任意 Invoice，Refund.equals 只接受编号相同的 Refund。普通发票与退款单编号相同，哪条 equals 契约已经被破坏？',
 '对称性，因为从两个方向比较得到的结果不同', '传递性，因为子类把相等判断限制在同一子类', '自反性，因为父类和子类的运行时类型不同', 'A',
 '普通发票接受退款单，退款单拒绝普通发票。对任意非空引用 a 和 b，a.equals(b) 与 b.equals(a) 应当给出相同结果。',
 'CANDIDATE_ACCOUNT', '牛客 · 阿里拍卖 Java 实习一面面经', 'https://www.nowcoder.com/discuss/353157591863861248?toCommentId=8560154',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/lang/Object.html#equals(java.lang.Object)'),
(202, 'java-qb-object-contracts', '调用者持有一个空的可变 List<String>。传给 fill(items) 后，方法先执行 items.add("草稿")，再执行 items = new ArrayList<>() 和 items.add("发布")。方法返回后，调用者的列表里有什么？',
 '只有“发布”', '先是“草稿”，再是“发布”', '只有“草稿”', 'C',
 '参数接收引用值的副本。第一次 add 修改了两边共同引用的列表，给参数重新赋值只改变方法内的引用，第二次 add 作用于新列表。',
 'COMMUNITY', 'JavaGuide · Java 的值传递', 'https://github.com/Snailclimb/JavaGuide/blob/main/docs/java/basis/why-there-only-value-passing-in-java.md',
 'https://docs.oracle.com/javase/specs/jls/se25/html/jls-15.html#jls-15.12.4.5'),
(203, 'java-qb-object-contracts', '结算模块用 String expected = "PAID" 定义目标状态。测试用 String actual = new String("PAID") 模拟收到的状态。哪组比较结果正确？',
 'actual == expected 为 true，actual.equals(expected) 为 true', 'actual == expected 为 false，actual.equals(expected) 为 true', 'actual == expected 为 false，actual.equals(expected) 为 false', 'B',
 '显式 new 创建了一个独立的 String 实例。引用比较因此为 false，但 String.equals 按字符序列比较，两个状态值的内容相同。',
 'CANDIDATE_ACCOUNT', '牛客 · 阿里拍卖 Java 实习一面面经', 'https://www.nowcoder.com/discuss/353157591863861248?toCommentId=8560154',
 'https://docs.oracle.com/javase/specs/jls/se25/html/jls-15.html#jls-15.21.3'),
(204, 'java-qb-object-contracts', 'Exporter 定义 export(Object)。CsvExporter 重写 export(Object)，同时重载 export(String)。执行 Exporter exporter = new CsvExporter() 后调用 exporter.export("报表")，会进入哪个实现？',
 'CsvExporter.export(Object)', 'CsvExporter.export(String)', 'Exporter.export(Object)', 'A',
 '编译器根据接收者的静态类型 Exporter 选定 export(Object) 签名。运行时按接收者的实际类型分派，执行 CsvExporter 对该签名的重写。',
 'COMMUNITY', 'JavaGuide-Interview · 重载与重写', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/java/java-basis.md#L662-L695',
 'https://docs.oracle.com/javase/specs/jls/se25/html/jls-15.html#jls-15.12'),
(205, 'java-qb-object-contracts', '配置解析器两次调用 Integer.valueOf(n)，并对两个 Integer 引用使用 ==。测试分别传入 n = 127 和 n = 128，Java SE 对结果有什么保证？',
 '127 和 128 都保证为 true', '127 保证为 true，128 的结果不由 API 保证', '127 保证为 true，128 保证为 false', 'B',
 'Integer.valueOf 保证缓存 -128 到 127 范围内的值，也允许缓存其他值。配置项按数值比较应使用 equals 或比较拆箱后的 int。',
 'CANDIDATE_ACCOUNT', '牛客 · 游族网络后端开发暑期实习一面面经', 'https://www.nowcoder.com/discuss/663794147907682304?sourceSSR=enterprise',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/lang/Integer.html#valueOf(int)'),
(206, 'java-qb-object-contracts', '接口 InvoiceSender 声明 void send(Invoice invoice)。实现类写了同签名的方法，但省略了访问修饰符。要保持接口签名并使实现通过编译，该如何调整？',
 '为实现方法加 protected，以便子类也能调用', '仅为实现方法加 @Override，保留包访问权限', '为实现方法加 public，并可保留 @Override', 'C',
 '该接口方法隐式为 public。实现公共方法时不能缩小可见性，@Override 只让编译器检查重写关系，无法改变访问权限。',
 'CANDIDATE_ACCOUNT', '牛客 · 腾讯 24 校招 Java 后端一二面面经', 'https://www.nowcoder.com/feed/main/detail/8682e4ae96114b588995ecad345bf31c',
 'https://docs.oracle.com/javase/specs/jls/se25/html/jls-8.html#jls-8.4.8.3'),
(207, 'java-qb-object-contracts', '对账模块把文本“19.0”和“19.00”分别传给 BigDecimal 的字符串构造器。记结果为 a 和 b。只按金额数值对账时，以下哪项准确？',
 'a.equals(b) 返回 true，a.compareTo(b) 返回 0', 'a.equals(b) 返回 false，a.compareTo(b) 返回 0', 'a.equals(b) 返回 false，a.compareTo(b) 返回非零值', 'B',
 '这两个金额数值相同，compareTo 返回 0。equals 还比较 scale，这两次构造产生的 scale 分别为 1 和 2。',
 'COMMUNITY', 'JavaGuide · BigDecimal 数值比较', 'https://github.com/Snailclimb/JavaGuide/blob/main/docs/java/basis/bigdecimal.md',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/math/BigDecimal.html#equals(java.lang.Object)'),
(208, 'java-qb-object-contracts', '日程对象 Schedule 实现了 Cloneable，clone() 直接返回 super.clone() 的结果。原对象持有 int[] slots。克隆后执行副本的 slots[0] = 9，且没有替换数组引用。原对象会观察到什么？',
 '原对象的 slots[0] 也变为 9', '只有原对象随后给 slots 重新赋值才会看到 9', '原对象仍看到旧值，因为 int 数组会按元素复制', 'A',
 'Object.clone 按字段浅拷贝。slots 字段保存数组引用，两个字段复制后仍引用同一个数组，写入数组元素对两个对象都可见。',
 'COMMUNITY', 'JavaGuide-Interview · 深拷贝与浅拷贝', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/java/java-basis.md#L977-L1032',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/lang/Object.html#clone()'),
-- Java 集合与泛型
(209, 'java-qb-collections-generics', '导入预览用 ArrayList 存放行记录。循环从 i = 0 开始逐项检查，发现无效行就调用 rows.remove(i)，每轮结束始终执行 i++。相邻两行都无效时，为何可能漏删？',
 'remove(i) 会按元素值查找，使索引仍然指向被删除的行', 'remove(i) 先把末尾元素移入空位，因此后续记录失去原有顺序', '后一条无效行左移到 i，循环却从 i + 1 继续', 'C',
 'ArrayList.remove(int) 删除指定索引并将后续元素左移。可以改用支持 remove 的迭代器，或从末尾向前遍历删除。',
 'CANDIDATE_ACCOUNT', '牛客 · 腾讯 24 校招 Java 后端一二面面经', 'https://www.nowcoder.com/feed/main/detail/8682e4ae96114b588995ecad345bf31c',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/ArrayList.html#remove(int)'),
(210, 'java-qb-collections-generics', '导出模块使用默认插入顺序的 LinkedHashMap。依次放入键 north、south、west，然后用 put 更新 south 的值。按 keySet 的迭代顺序导出时，顺序是什么？',
 'north、west、south', 'north、south、west', 'south、north、west', 'B',
 '插入顺序的 LinkedHashMap 对已存在的键重新 put 时只更新映射值，键保留原有位置。更新顺序的行为要区分访问顺序模式。',
 'CANDIDATE_ACCOUNT', '牛客 · 阿里拍卖 Java 实习一面面经', 'https://www.nowcoder.com/discuss/353157591863861248?toCommentId=8560154',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/LinkedHashMap.html'),
(211, 'java-qb-collections-generics', '仓储系统发现两个不同货位的 SlotKey 恰好返回同一个 hashCode，不过 equals 区分仓库编号和货位编号。把这两个键分别 put 进 HashMap，会怎样？',
 '两条映射并存，可以按各自的键查询', '后写入的值覆盖先写入的值，因为散列相同', '第二次 put 因散列冲突抛出异常', 'A',
 '哈希值帮助定位候选映射，键的相等性决定是否替换已有值。相同散列值允许产生冲突，此处 equals 可以区分两个键。',
 'CANDIDATE_ACCOUNT', '牛客 · 阿里拍卖 Java 实习一面面经', 'https://www.nowcoder.com/discuss/353157591863861248?toCommentId=8560154',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/Map.html#get(java.lang.Object)'),
(212, 'java-qb-collections-generics', '活动系统用 TreeSet 存放参赛队，equals 按队伍 ID 区分，Comparator 却只比较得分。两队得分相同，后添加的一队未入集合。如何保留同分队伍并继续按得分排序？',
 '让 equals 在得分相同时仍比较 ID，保留现有 Comparator', '让 hashCode 由队伍 ID 和得分共同生成，保留现有 Comparator', '让 Comparator 先比较得分，再在同分时比较队伍 ID', 'C',
 'TreeSet 按比较结果判断元素在集合中是否等价。仅比较得分会返回 0，使用稳定且唯一的队伍 ID 打破平局可让两队并存。',
 'COMMUNITY', 'JavaGuide-Interview · 排序比较器与 TreeSet', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/java/java-collection.md#L300-L434',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/TreeSet.html'),
(213, 'java-qb-collections-generics', '通知分发使用 CopyOnWriteArrayList<Listener>。分发线程已创建迭代器，注册线程随后添加一个监听器，并且添加已完成。这轮分发与下一次新建迭代器各会看到什么？',
 '当前迭代器看不到新监听器，后来创建的迭代器可以看到', '只要还没遍历到末尾，当前迭代器就能看到新监听器', '当前迭代器抛出并发修改异常，后来创建的迭代器可以看到新监听器', 'A',
 'CopyOnWriteArrayList 的迭代器引用创建时的数组快照。追加元素会发布新数组，旧迭代器继续遍历旧数组。',
 'CANDIDATE_ACCOUNT', '牛客 · 阿里拍卖 Java 实习一面面经', 'https://www.nowcoder.com/discuss/353157591863861248?toCommentId=8560154',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/concurrent/CopyOnWriteArrayList.html'),
(214, 'java-qb-collections-generics', '统计方法只遍历数字并调用 doubleValue()。它要直接接收 List<Integer> 和 List<Double>，不使用原始类型或强制转换。形参应选哪种类型？',
 'List<Number>', 'List<? extends Number>', 'List<? super Number>', 'B',
 '上界通配符允许列表的元素类型为 Number 或其子类型，读取元素时可按 Number 使用。List<Number> 和下界为 Number 的列表都不接受 List<Integer>。',
 'COMMUNITY', 'JavaGuide · 泛型上界通配符', 'https://github.com/Snailclimb/JavaGuide/blob/main/docs/java/basis/generics-and-wildcards.md#L276',
 'https://docs.oracle.com/javase/specs/jls/se25/html/jls-4.html#jls-4.5.1'),
(215, 'java-qb-collections-generics', '排班工具想在同一个类里声明 void schedule(List<LocalDate> dates) 和 void schedule(List<Instant> times)。这两个方法能直接构成重载吗？',
 '能，编译器会把元素类型写入两个不同的 JVM 方法签名', '能，只要调用者传入的变量声明使用具体的元素类型', '不能，两个参数类型擦除后都是 List', 'C',
 'Java 禁止同一类中出现这种签名擦除相同的方法声明。可以改用不同的方法名，或用两个真正不同的参数类型表达不同输入。',
 'COMMUNITY', 'JavaGuide · 泛型擦除', 'https://github.com/Snailclimb/JavaGuide/blob/main/docs/java/basis/generics-and-wildcards.md#L116',
 'https://docs.oracle.com/javase/specs/jls/se25/html/jls-8.html#jls-8.4.8.3'),
(216, 'java-qb-collections-generics', '调度器已用 PriorityQueue 按截止时间从早到晚比较任务。现在要从一个已独占且允许清空的队列按此顺序生成清单。哪种遍历有顺序保证？',
 '反复调用 poll()，直到队列为空', '用 for-each 遍历 PriorityQueue', '先调用 toArray()，按数组下标依次读取', 'A',
 'poll 每次删除并返回当前队首，即比较规则下的最小元素。PriorityQueue 的迭代器及 toArray 返回结果均不承诺按优先级排序。',
 'COMMUNITY', 'JavaGuide-Interview · PriorityQueue', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/java/java-collection.md#L475-L487',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/PriorityQueue.html'),
-- Java 并发
(217, 'java-qb-concurrency', '多条工作线程各完成一次任务就执行 volatile int 字段 completed 的自增。所有线程结束后，计数偶尔偏小。哪项改动能让每次完成都被计入？',
 '将 completed 改成 volatile long，仍执行 completed++', '改用 AtomicInteger，对每次完成调用 incrementAndGet()', '保留 volatile int，把自增移到一个普通方法中执行', 'B',
 '自增包含读取、计算和写回。volatile 保证单次读写的可见性，却不能把三步合为一次原子操作。incrementAndGet 原子递增并返回结果。',
 'CANDIDATE_ACCOUNT', '牛客 · 阿里拍卖 Java 实习一面面经', 'https://www.nowcoder.com/discuss/353157591863861248?toCommentId=8560154',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/concurrent/atomic/AtomicInteger.html#incrementAndGet()'),
(218, 'java-qb-concurrency', '固定线程池的任务先把租户 ID 写入 ThreadLocal，再执行业务。任务失败后，同一线程处理下一个任务时有机会读到旧值。应在哪里清理？',
 '提交任务后，在提交者线程中调用 remove()', '任务成功返回后调用 remove()，异常交给线程池处理', '在工作任务自己的 finally 中调用 remove()', 'C',
 'ThreadLocal.remove 只删除调用线程的副本。业务运行所在的工作线程可能被复用，finally 可以覆盖正常返回和抛异常两条路径。',
 'CANDIDATE_ACCOUNT', '牛客 · 运去哪一面面经', 'https://www.nowcoder.com/discuss/733349258476220416',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/lang/ThreadLocal.html#remove()'),
(219, 'java-qb-concurrency', '运行中的 ThreadPoolExecutor 配置核心线程 2、最大线程 4、队列容量 1。当前 2 个工作线程都在阻塞，队列已有 1 个任务。期间状态不变且允许创建线程，新提交的任务怎么处理？',
 '创建一个额外的工作线程执行该任务', '触发拒绝策略，因为队列已经满了', '由提交线程等待队列腾出位置后再入队', 'A',
 '达到核心线程数后，线程池先尝试入队。队列放不下且工作线程数仍低于最大值时，会尝试创建工作线程接手新任务。',
 'CANDIDATE_ACCOUNT', '牛客 · 游族网络后端开发暑期实习一面面经', 'https://www.nowcoder.com/discuss/663794147907682304?sourceSSR=enterprise',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/concurrent/ThreadPoolExecutor.html#class-description'),
(220, 'java-qb-concurrency', '报表服务调用 ExecutorService.submit(Callable) 成功返回 Future。任务运行时因输入损坏抛出 IllegalArgumentException，调用方随后正常等待 future.get()。如何取得原异常？',
 '直接捕获 future.get() 抛出的 IllegalArgumentException', '捕获 future.get() 抛出的 ExecutionException，再取 getCause()', '捕获 future.get() 抛出的 CancellationException，再取 getCause()', 'B',
 'Future.get 用 ExecutionException 报告任务执行失败，原始异常在 cause 中。CancellationException 表示任务已取消。',
 'COMMUNITY', 'JavaGuide-Interview · 线程池任务异常', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/java/java-concurrent.md#L1828-L1837',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/concurrent/Future.html#get()'),
(221, 'java-qb-concurrency', '后台任务用 ReentrantLock.tryLock() 尝试更新任务簿。只有拿到锁才允许更新，更新途中还可能抛异常。以下哪种结构能正确释放锁？',
 '把 tryLock 放进 try 内，在 finally 中无条件 unlock', 'tryLock 成功后，在更新正常返回时 unlock', '仅在 tryLock 成功后进入 try，在对应的 finally 中 unlock', 'C',
 '只有获取锁的线程才能释放这次获取。将更新放进成功分支的 try，并在相应 finally 中解锁，既能覆盖异常也不会误释放未取得的锁。',
 'COMMUNITY', 'JavaGuide-Interview · ReentrantLock 的高级功能', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/java/java-concurrent.md#L1036-L1130',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/concurrent/locks/Lock.html'),
(222, 'java-qb-concurrency', '初始化线程是普通 int 字段 reportCount 的唯一写入者，退出前把它设为 42。监控线程启动它后调用无超时的 worker.join()，确认 join 正常返回再读该字段。能保证读到什么？',
 '字段不是 volatile，因此仍可能读到初始值', '可以读到 42，因为工作线程的操作先行发生于 join 的成功返回', 'join 只约束线程何时结束，还得同步访问字段才有保证', 'B',
 'Java 内存模型规定，线程中的所有动作先行发生于另一个线程从其 join 成功返回。此处 join 建立了写入与随后读取之间的可见性。',
 'CANDIDATE_ACCOUNT', '牛客 · 腾讯 24 校招 Java 后端一二面面经', 'https://www.nowcoder.com/feed/main/detail/8682e4ae96114b588995ecad345bf31c',
 'https://docs.oracle.com/javase/specs/jls/se25/html/jls-17.html#jls-17.4.5'),
(223, 'java-qb-concurrency', '两个平台线程可能分别持有一把 ReentrantLock，并互相等待对方的锁。JVM 支持监测自有同步器。进程内诊断希望直接取得死锁参与线程的 ID，应调用什么？',
 'ThreadMXBean.findDeadlockedThreads()', 'ThreadMXBean.findMonitorDeadlockedThreads()', 'ThreadMXBean.getAllThreadIds()', 'A',
 'findDeadlockedThreads 检测涉及对象监视器或自有同步器的循环等待。findMonitorDeadlockedThreads 只覆盖对象监视器，getAllThreadIds 不区分是否处于死锁。',
 'COMMUNITY', 'JavaGuide-Interview · Java 死锁排查', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/java/java-concurrent.md#L311-L333',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.management/java/lang/management/ThreadMXBean.html#findDeadlockedThreads()'),
(224, 'java-qb-concurrency', '服务迁移到每个任务一个虚拟线程。只有其中一个旧版同步 HTTP 接口最多允许本服务同时发起 20 次调用，其他调用不受这个上限影响。如何实施这个限制？',
 '把虚拟线程调度器的并行度设为 20，靠调度并行度限制在途调用', '把整个服务的任务提交速率限制为每秒 20 个', '为该接口配置 20 个 Semaphore 许可，调用前获取并在结束后释放', 'C',
 '许可证直接约束该接口的在途调用数量，即使等待响应的虚拟线程让出载体线程，仍持有许可。每秒调用速率和载体并行度都无法表达这个上限。',
 'COMMUNITY', 'JavaGuide · 虚拟线程与下游资源限流', 'https://github.com/Snailclimb/JavaGuide/blob/main/docs/java/concurrent/virtual-thread.md#L190-L219',
 'https://docs.oracle.com/en/java/javase/25/core/virtual-threads.html'),
-- JVM 类加载与内存
(225, 'java-qb-jvm', '两个插件加载器分别通过 defineClass 定义了同一份 demo.PluginImpl 字节码。得到的 Class 对象都代表这个实现类。用加载器甲返回的 Class.cast 转换由加载器乙创建的实例，结果是什么？',
 '转换失败，因为同名类的定义加载器不同', '转换成功，因为两份字节码逐字节相同', '转换成功，因为两个实现类来自同一个包名', 'A',
 '运行时类身份由二进制名称和定义它的类加载器共同确定。各自定义的同名类是不同类型，甲的 Class.cast 不接受乙的实例。',
 'CANDIDATE_ACCOUNT', '牛客 · 26 届淘天暑期后端一面', 'https://www.nowcoder.com/discuss/734830070774104064',
 'https://docs.oracle.com/javase/specs/jvms/se25/html/jvms-5.html#jvms-5.3'),
(226, 'java-qb-jvm', '宿主和插件内部各带同名的共享接口。插件 ClassLoader 未重写 loadClass(String, boolean)，子加载器尚未发起过该类的加载，而且父加载器能成功加载此接口。这次请求会用哪个类？',
 '子加载器先定义插件内的接口，定义失败再查询父加载器', '子加载器比较两个 JAR 的版本号，使用较新的接口', '使用父加载器返回的接口类，子加载器自己的 findClass 不会为它执行', 'C',
 'ClassLoader 的默认实现先检查已加载类，再委派父加载器。只有委派未找到时才调用自己的 findClass，因此此处采用父加载器返回的类。',
 'CANDIDATE_ACCOUNT', '牛客 · 游族网络后端开发暑期实习一面面经', 'https://www.nowcoder.com/discuss/663794147907682304?sourceSSR=enterprise',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/lang/ClassLoader.html#loadClass(java.lang.String,boolean)'),
(227, 'java-qb-jvm', 'Flags 类尚未初始化。它声明 static final int MASK = 8 和 static int retries = 3，另有一段打印日志的静态块。另一类直接读取这两个字段，哪次读取会触发初始化？',
 '首次读取 MASK，因为访问了 Flags 的静态字段', '首次读取 retries，因为它不是常量变量', '两次读取都不会，只有创建 Flags 实例才触发', 'B',
 'MASK 是用常量表达式初始化的 final 基本类型变量，读取它不会触发初始化。首次主动读取 Flags 声明的静态字段 retries 则会触发。',
 'CANDIDATE_ACCOUNT', '牛客 · 京东 Java 实习一面复盘', 'https://www.nowcoder.com/discuss/353157647211896832',
 'https://docs.oracle.com/javase/specs/jls/se25/html/jls-12.html#jls-12.4.1'),
(228, 'java-qb-jvm', '递归遍历器遇到循环引用，未调用任何对象分配逻辑，只不断增加同一线程的递归调用深度，直到超过 JVM 允许的栈大小。此时 JVM 抛出哪个错误？',
 'StackOverflowError', 'OutOfMemoryError: Java heap space', 'OutOfMemoryError: Metaspace', 'A',
 '每次方法调用都会需要新栈帧。线程计算所需的 JVM 栈超过允许大小时，JVM 抛出 StackOverflowError。',
 'COMMUNITY', 'JavaGuide-Interview · JVM 栈错误', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/java/java-jvm.md#L75-L81',
 'https://docs.oracle.com/javase/specs/jvms/se25/html/jvms-2.html#jvms-2.5.2'),
(229, 'java-qb-jvm', '服务在多次垃圾收集后堆占用仍持续上升。维护窗口允许采样，现在需要拿到具体对象及其引用关系，以便分析哪些对象把缓存条目留在堆上。应收集什么？',
 'jcmd <pid> GC.class_histogram 的类级统计', 'jcmd <pid> GC.heap_dump heap.hprof 生成的堆转储', 'jcmd <pid> Thread.print 的线程栈快照', 'B',
 '堆转储保存对象及其引用，可用于追踪缓存条目到 GC Roots 的路径。类直方图适合粗筛数量和大小，线程栈则反映线程执行状态。',
 'CANDIDATE_ACCOUNT', '牛客 · 26 届淘天暑期后端一面', 'https://www.nowcoder.com/discuss/734830070774104064',
 'https://docs.oracle.com/en/java/javase/25/docs/specs/man/jcmd.html#commands-for-jcmd'),
(230, 'java-qb-jvm', '两个普通节点仅相互持有强引用。处理完批次后，程序删除了外部对它们的最后引用，且没有任何存活线程能从其他地方到达它们。GC 如何处理这对节点？',
 '两者强引用计数都大于零，因此 GC 会一直保留', '只有把其中一个成员显式设为 null 后，GC 才会考虑回收', '两者组成的环无法从 GC Roots 到达，因此可以回收', 'C',
 '能否从根到达决定这里的可回收性。环内部的引用无法让这一组对象保持可达，实际回收时间由垃圾收集器决定。',
 'CANDIDATE_ACCOUNT', '牛客 · 腾讯 24 校招 Java 后端一二面面经', 'https://www.nowcoder.com/feed/main/detail/8682e4ae96114b588995ecad345bf31c',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/lang/ref/package-summary.html#reachability'),
(231, 'java-qb-jvm', '解析失败时，工程师检查 parse 方法字节码执行状态，想找到本次调用的局部变量槽和操作数栈。按 JVM 规范，这两者随什么创建？',
 '随每个类的运行时常量池创建，供这个类的方法调用共享', '随每次方法调用的栈帧创建，每次调用有自己的槽和操作数栈', '随接收者对象创建，递归调用共享同一组槽和操作数栈', 'B',
 '每次方法调用创建新帧。帧包含本次调用的局部变量数组和操作数栈，调用同一方法的不同帧各自保存执行状态。',
 'CANDIDATE_ACCOUNT', '牛客 · 京东 Java 实习一面复盘', 'https://www.nowcoder.com/discuss/353157647211896832',
 'https://docs.oracle.com/javase/specs/jvms/se25/html/jvms-2.html#jvms-2.6'),
(232, 'java-qb-jvm', '预览组件保留 WeakReference<Image> 以便复用。业务代码已释放对图像的所有强引用，且没有软引用等其他保留路径。当 GC 判定图像为弱可达时，get() 会如何变化？',
 '弱引用被清除，此后 get() 返回 null', '必须等应用主动从 ReferenceQueue 取走引用，get() 才会返回 null', '只要 WeakReference 对象本身仍存活，get() 就一直返回图像', 'A',
 '收集器判定对象弱可达后会清除相应弱引用。注册的引用对象可在同一时刻或稍后入队，清除不需要应用先消费队列。',
 'COMMUNITY', 'JavaGuide-Interview · JVM 的弱引用', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/java/java-jvm.md#L287-L351',
 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/lang/ref/WeakReference.html'),
-- Spring 依赖注入与 MVC
(233, 'java-qb-spring-di-mvc', '一个由 Spring 扫描注册的 @Service 只有一个未标注 @Autowired 的构造器，参数是容器中唯一的 TaxPolicy Bean。容器怎样创建该服务？',
 '因为构造器缺少 @Autowired，容器要求再声明一个无参构造器', '容器需要为 TaxPolicy 加 @Primary 才能调用这个未标注的构造器', '容器使用唯一的构造器并注入 TaxPolicy', 'C',
 'Spring 自动选择 Bean 的唯一构造器，@Autowired 对此可省略。TaxPolicy 只有一个候选者，因此直接解析该参数。',
 'COMMUNITY', 'JavaGuide-Interview · Spring 构造器注入', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/system-design/spring.md#L217-L288',
 'https://docs.spring.io/spring-framework/reference/7.0/core/beans/annotation-config/autowired.html'),
(234, 'java-qb-spring-di-mvc', '容器有两个 Storage Bean，分别标为 hot 和 archive 限定符。归档服务的构造器应固定注入 archive，而其他 Storage 注入点的候选规则无需改变。如何声明这个依赖？',
 '把 archive Bean 标为 @Primary，让所有单值 Storage 注入优先使用它', '在归档服务的 Storage 构造器参数上加 @Qualifier("archive")', '在归档服务的构造器上加 @Autowired(required = false) 以选中 archive', 'B',
 '@Qualifier 将这个注入点的同类型候选限制为 archive。@Primary 会影响其他同类型的单值注入，required 属性也不用于选择具体实现。',
 'COMMUNITY', 'JavaGuide-Interview · Spring 同类型 Bean 的注入', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/system-design/spring.md#L148-L176',
 'https://docs.spring.io/spring-framework/reference/7.0/core/beans/annotation-config/autowired-qualifiers.html'),
(235, 'java-qb-spring-di-mvc', '一个 singleton 报表服务通过构造器直接注入 prototype 草稿对象，没有作用域代理。该服务每次处理报表都使用同一个字段，为什么草稿数据会在两次调用之间残留？',
 'prototype 依赖在单例创建时解析一次，字段一直持有当时创建的实例', 'prototype 每次方法调用都会创建新实例，数据残留来自两个新实例共享 Bean 名称', '容器会按调用线程缓存 prototype，同一线程调用时固定复用实例', 'A',
 '直接注入只在单例实例化时获取一次依赖。若每次操作需要新草稿，可以注入 ObjectProvider<ReportDraft>，每次调用 getObject() 获取新实例。',
 'COMMUNITY', 'JavaGuide-Interview · Spring Bean 的作用域', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/system-design/spring.md#L289-L317',
 'https://docs.spring.io/spring-framework/reference/7.0/core/beans/factory-scopes.html#beans-factory-scopes-sing-prot-interaction'),
(236, 'java-qb-spring-di-mvc', '两个 Spring 服务都要求在构造器里直接拿到对方，且都没有 @Lazy 或 ObjectProvider。即使容器允许尝试解析循环引用，为什么创建仍会失败？',
 '服务没有无参构造器，Spring 只能通过字段执行依赖注入', '容器通过调整 Bean 的注册顺序可以任选一个服务先创建', '任一构造器执行前都需要对方实例，容器无法先完成其中一个构造', 'C',
 '双方都要求一个尚未构造的对象，形成不可解析的构造器循环依赖。可将共同职责抽为第三个依赖，让这两个服务无需直接互相依赖。',
 'COMMUNITY', 'JavaGuide-Interview · Spring 循环依赖', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/system-design/spring.md#L719-L748',
 'https://docs.spring.io/spring-framework/reference/7.0/core/beans/dependencies/factory-collaborators.html#beans-dependency-resolution'),
(237, 'java-qb-spring-di-mvc', '排查一个 Spring MVC 请求时，已经确认 HandlerMapping 找到了正确的控制器方法。下一步，DispatcherServlet 通过哪个组件适配并调用处理器？',
 'HandlerAdapter', 'ViewResolver', 'HandlerExceptionResolver', 'A',
 'HandlerMapping 查找处理器，HandlerAdapter 知道如何调用具体类型的处理器。视图解析与异常解析分别用于后续的不同路径。',
 'COMMUNITY', 'JavaGuide-Interview · Spring MVC 请求分派', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/system-design/spring.md#L618-L644',
 'https://docs.spring.io/spring-framework/docs/7.0.x/javadoc-api/org/springframework/web/servlet/HandlerAdapter.html#handle(jakarta.servlet.http.HttpServletRequest,jakarta.servlet.http.HttpServletResponse,java.lang.Object)'),
(238, 'java-qb-spring-di-mvc', '导入接口收到 Content-Type 为 application/json 的 POST，请求体是 {"fileName":"march.csv"}，参数类型是 ImportRequest。系统已配置 JSON 消息转换器。哪个注解让 Spring MVC 从请求体构造该参数？',
 '@RequestParam', '@RequestBody', '@ModelAttribute', 'B',
 '@RequestBody 让 HttpMessageConverter 从 HTTP 请求体反序列化目标对象。@RequestParam 用于请求参数，@ModelAttribute 的绑定也不负责反序列化这个 JSON 请求体。',
 'COMMUNITY', 'GitHub · Spring REST API 面试笔记的请求体绑定', 'https://github.com/rutujamungse16/Notes/blob/main/Java/spring-boot-rest-api-interview-guide.md#L121',
 'https://docs.spring.io/spring-framework/reference/7.0/web/webmvc/mvc-controller/ann-methods/requestbody.html'),
(239, 'java-qb-spring-di-mvc', '页面控制器被改成 @RestController 后，原本返回 "reports/monthly" 的方法开始在浏览器显示这串文字。若要恢复模板渲染，应怎样处理？',
 '保留 @RestController，给方法添加 @ResponseBody', '保留 @RestController，给方法指定 produces = "text/html"', '使用 @Controller，方法直接返回视图名并省略 @ResponseBody', 'C',
 '@RestController 包含 @ResponseBody 语义，字符串会作为响应内容处理。普通 @Controller 的字符串返回值可以由 ViewResolver 解析为模板视图。',
 'CANDIDATE_ACCOUNT', '牛客 · 小红书测试开发一面面经', 'https://www.nowcoder.com/feed/main/detail/c701af98e9cc4edd9024fa563e5fa6ee',
 'https://docs.spring.io/spring-framework/reference/7.0/web/webmvc/mvc-controller/ann-methods/return-types.html'),
(240, 'java-qb-spring-di-mvc', '多个 REST 控制器都会抛出同一种业务异常。团队希望只编写一次处理方法，将它统一转换为带 JSON 错误对象的 HTTP 409。哪种做法符合 Spring MVC 的处理流程？',
 '在 @RestControllerAdvice 中定义 @ExceptionHandler，并返回带 409 的 ResponseEntity', '在任意一个控制器内定义 @ExceptionHandler，由同包的其他控制器自动共享', '在 @RestControllerAdvice 中定义 @ModelAttribute 方法，由它接管异常映射', 'A',
 '@RestControllerAdvice 将通知方法应用到匹配的控制器，并提供响应体语义。@ExceptionHandler 选择可处理的异常，ResponseEntity 明确指定 HTTP 状态和响应体。',
 'COMMUNITY', 'JavaGuide-Interview · Spring MVC 统一异常处理', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/system-design/spring.md#L656-L705',
 'https://docs.spring.io/spring-framework/reference/7.0/web/webmvc/mvc-controller/ann-advice.html'),
-- Spring 事务与 JPA
(241, 'java-qb-spring-tx-jpa', '订单事务通过代理调用另一 Bean 的 REQUIRES_NEW 方法记录一次操作。内层审计事务已正常提交，外层订单随后因非法状态回滚。两笔写入结果如何？',
 '订单和审计都回滚，内层提交依附于外层', '订单回滚，审计记录仍然存在', '订单和审计都保留，审计提交时也提交了外层', 'B',
 'REQUIRES_NEW 使用独立的物理事务。内层提交完成后，恢复执行的外层事务可以单独回滚，已经提交的审计记录不会随它撤回。',
 'CANDIDATE_ACCOUNT', '牛客 · BOSS 直聘 Java 后端一面', 'https://www.nowcoder.com/discuss/801379399596535808?sourceSSR=enterprise',
 'https://docs.spring.io/spring-framework/reference/7.0/data-access/transaction/declarative/tx-propagation.html#tx-propagation-requires_new'),
(242, 'java-qb-spring-tx-jpa', 'Spring 使用默认代理模式，当前没有事务。ImportService 的普通方法直接调用 this.persistBatch()，后者是同一类中带 @Transactional 的 public 方法。怎样让这个批次方法经事务拦截器调用？',
 '在普通方法内省略 this，改为直接写 persistBatch()', '保留原调用并把事务传播行为改为 REQUIRES_NEW', '把持久化方法移到另一个注入的 Spring Bean，并通过该 Bean 调用', 'C',
 '同一个对象内部调用不会经过 Spring 事务代理，传播属性也就不会被读取。调用另一个受事务代理管理的 Bean，才会经过相应拦截。',
 'CANDIDATE_ACCOUNT', '牛客 · BOSS 直聘 Java 后端一面', 'https://www.nowcoder.com/discuss/801379399596535808?sourceSSR=enterprise',
 'https://docs.spring.io/spring-framework/reference/7.0/data-access/transaction/declarative/annotations.html'),
(243, 'java-qb-spring-tx-jpa', '启用 Spring 默认事务回滚规则的导入服务先写数据库，再读清单文件。若 IOException 直接抛出事务代理边界，要求这类失败也回滚。应该怎样配置？',
 '@Transactional(rollbackFor = IOException.class)', '@Transactional(noRollbackFor = IOException.class)', '@Transactional(readOnly = false)', 'A',
 'IOException 是受检异常，在默认规则下不触发回滚。rollbackFor 将它及其子类列入回滚条件，readOnly 则与按异常类型回滚无关。',
 'COMMUNITY', 'JavaGuide-Interview · Spring 按异常类型回滚', 'https://github.com/Snailclimb/JavaGuide-Interview/blob/master/docs/system-design/spring.md#L952-L979',
 'https://docs.spring.io/spring-framework/reference/7.0/data-access/transaction/declarative/rolling-back.html'),
(244, 'java-qb-spring-tx-jpa', '价格服务开启新的 READ_COMMITTED 事务，数据库支持该隔离级别。事务内两次查询同一价格，中间有其他事务修改并提交。只依据该隔离级别能作出什么判断？',
 '两次查询必然读到相同价格，因为每笔事务固定读首次查询的快照', '不会读到其他事务未提交的价格，两次查询仍可能得到不同结果', '第一次可以读到未提交价格，第二次才能保证读到已提交价格', 'B',
 'READ_COMMITTED 禁止脏读，但允许不可重复读。其他事务若在两次读取之间完成提交，第二次就有可能看到新价格。',
 'CANDIDATE_ACCOUNT', '牛客 · 腾讯 24 校招 Java 后端一二面面经', 'https://www.nowcoder.com/feed/main/detail/8682e4ae96114b588995ecad345bf31c',
 'https://docs.spring.io/spring-framework/docs/7.0.x/javadoc-api/org/springframework/transaction/annotation/Isolation.html#READ_COMMITTED'),
(245, 'java-qb-spring-tx-jpa', '发票服务在已加入事务的 EntityManager 中 find 到一张发票，修改其可更新的映射字段 memo。发票一直处于托管状态，事务正常提交。还需要显式调用 persist 或 merge 才能保存这项修改吗？',
 '需要调用 persist，因为 find 只管理原始字段值', '需要调用 merge，因为每次 setter 都会让实体分离', '无需显式调用，托管实体的修改最晚在事务提交时同步到数据库', 'C',
 '持久化上下文管理 find 返回的实体。事务同步时会写入托管状态的变更，因此此次普通字段修改不需要额外调用持久化操作。',
 'COMMUNITY', 'GitHub · Interviewsmith JPA 面试准备：脏检查', 'https://github.com/AnshulAg03/interviewsmith/blob/master/Frameworks/JPA_Hibernate_Interview_Prep.md#L569',
 'https://jakarta.ee/specifications/persistence/3.2/jakarta-persistence-spec-3.2#a1955'),
(246, 'java-qb-spring-tx-jpa', '编辑服务在新事务中执行 Invoice managed = em.merge(detached)，原对象 detached 来自已关闭的持久化上下文。merge 成功后还要修改 memo，应该改哪个对象以让此次修改随同一事务写入？',
 '改 detached，merge 会把传入实例重新变成托管状态', '改 managed，它是 merge 返回的托管实例', '改任意一个，merge 会持续同步两个对象之间的后续修改', 'B',
 'merge 将分离实体的状态复制到托管实例并返回它。传入对象仍是分离状态，后续修改应施加在返回的托管实例上。',
 'COMMUNITY', 'GitHub · Interviewsmith JPA 面试准备：merge 的实体状态', 'https://github.com/AnshulAg03/interviewsmith/blob/master/Frameworks/JPA_Hibernate_Interview_Prep.md#L972',
 'https://jakarta.ee/specifications/persistence/3.2/jakarta-persistence-spec-3.2#a1983'),
(247, 'java-qb-spring-tx-jpa', '无分页的发票导出加载一批 Invoice。遍历时每次读取延迟加载的 customer 都可能额外查询。customer 有的为空，导出要保留这些发票。哪条 JPQL 能为这一个查询预取关联并保留所有发票？',
 'select i from Invoice i left join fetch i.customer', 'select i from Invoice i join fetch i.customer', 'select i from Invoice i left join i.customer c', 'A',
 'LEFT JOIN FETCH 同时指定预取关联和左连接语义。内连接 fetch 会过滤无客户的发票，普通 LEFT JOIN 只描述连接，未要求预取关联。',
 'COMMUNITY', 'GitHub · Interviewsmith JPA 面试准备：N+1 与抓取连接', 'https://github.com/AnshulAg03/interviewsmith/blob/master/Frameworks/JPA_Hibernate_Interview_Prep.md#L736',
 'https://jakarta.ee/specifications/persistence/3.2/jakarta-persistence-spec-3.2#a4931'),
(248, 'java-qb-spring-tx-jpa', '两个独立事务都读到带 @Version 的资料实体，版本都是 7。它们各自修改同一映射字段，第一个事务成功提交后，第二个事务才同步自己的修改。JPA 对第二个事务的写入如何处理？',
 '允许写入并覆盖第一笔修改，因为第二个事务最后提交', '把第二次修改与第一笔修改自动合并，再更新版本号', '版本检查失败，第二个事务将回滚', 'C',
 '带 @Version 的实体在写入时需要通过版本检查。第一笔提交后，旧版本不能再更新同一行。JPA 实现检测到冲突时会报告 OptimisticLockException，并标记事务回滚。',
 'COMMUNITY', 'GitHub · Interviewsmith JPA 面试准备：乐观锁', 'https://github.com/AnshulAg03/interviewsmith/blob/master/Frameworks/JPA_Hibernate_Interview_Prep.md#L1298',
 'https://jakarta.ee/specifications/persistence/3.2/jakarta-persistence-spec-3.2#a2059');
